 "content": "from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    # Find a solid monochrome row/column divider that splits the grid into
    # equally sized repeated panels; choose the orientation with the most bars.
    candidates = []
    for axis in (0, 1):
        n = h if axis == 0 else w
        m = w if axis == 0 else h
        bars = []
        for i in range(n):
            line = [grid[i][j] for j in range(w)] if axis == 0 else [grid[j][i] for j in range(h)]
            if len(set(line)) == 1:
                bars.append((i, line[0]))
        for color in set(c for _, c in bars):
            positions = [i for i, c in bars if c == color]
            if not positions:
                continue
            # Consecutive solid lines of the same color form one thick divider.
            groups = []
            for i in positions:
                if not groups or i > groups[-1][-1] + 1:
                    groups.append([i])
                else:
                    groups[-1].append(i)
            cuts = [(g[0], g[-1] + 1) for g in groups]
            spans = []
            prev = 0
            for a, b in cuts:
                if a > prev:
                    spans.append((prev, a))
                prev = b
            if prev < n:
                spans.append((prev, n))
            if len(spans) < 2:
                continue
            lengths = [b-a for a,b in spans]
            if len(set(lengths)) != 1:
                continue
            # Ignore degenerate full-axis lines.
            candidates.append((len(cuts), axis, spans, color))
    if not candidates:
        return out
    _, axis, spans, sep_color = max(candidates, key=lambda x: (x[0], x[1] == 0))

    # The panel containing the most non-background marks is the exemplar.
    vals = [v for row in grid for v in row]
    bg = Counter(vals).most_common(1)[0][0]
    def panel_score(span):
        a,b = span
        cells = (grid[i][j] for i in range(a,b) for j in range(w)) if axis == 0 else (grid[i][j] for j in range(a,b) for i in range(h))
        return sum(v != bg for v in cells)
    source = max(spans, key=panel_score)
    sa, sb = source
    for a,b in spans:
        if (a,b) == source:
            continue
        for offset in range(b-a):
            src = sa + offset
            dst = a + offset
            if axis == 0:
                out[dst] = grid[src][:]
            else:
                for r in range(h):
                    out[r][dst] = grid[r][src]
    return out
